(r, big) => {
    const n = big ? 100 : r.int(1, 4);
    const cells = [];
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) cells.push([i, j]);
    const order = r.shuffle(cells);
    const owner = Array.from({ length: n }, () => new Array(n).fill(0));
    const ops = ["TicTacToe"], args = [[n]];
    const wins = (i, j, p) => {
      let row = true, col = true, d = i === j, a = i + j === n - 1;
      for (let k = 0; k < n; k++) {
        if (owner[i][k] !== p) row = false;
        if (owner[k][j] !== p) col = false;
        if (owner[k][k] !== p) d = false;
        if (owner[k][n - 1 - k] !== p) a = false;
      }
      return row || col || d || a;
    };
    const stripe = big ? r.int(0, n - 1) : -1;
    for (const [i, j] of order) {
      // in the big case player 1 tends to own one column, so a late win is likely
      const p = big ? (j === stripe ? 1 : r.int(1, 2)) : r.int(1, 2);
      owner[i][j] = p;
      ops.push("move"); args.push([i, j, p]);
      if (wins(i, j, p)) break;
    }
    return { ops, args };
  }

