class TicTacToe:
    def __init__(self, n: int):
        self.n = n
        self.board = [[0] * n for _ in range(n)]

    def move(self, row: int, col: int, player: int) -> int:
        b, n = self.board, self.n
        b[row][col] = player
        if all(b[row][k] == player for k in range(n)):
            return player
        if all(b[k][col] == player for k in range(n)):
            return player
        if row == col and all(b[k][k] == player for k in range(n)):
            return player
        if row + col == n - 1 and all(b[k][n - 1 - k] == player for k in range(n)):
            return player
        return 0

