class TicTacToe {
  private rows: number[];
  private cols: number[];
  private diag = 0;
  private anti = 0;

  constructor(private n: number) {
    this.rows = new Array(n).fill(0);
    this.cols = new Array(n).fill(0);
  }

  move(row: number, col: number, player: number): number {
    const d = player === 1 ? 1 : -1, n = this.n;
    this.rows[row] += d;
    this.cols[col] += d;
    if (row === col) this.diag += d;
    if (row + col === n - 1) this.anti += d; // not "else": the centre is on both
    const hit = [this.rows[row], this.cols[col], this.diag, this.anti].some(v => Math.abs(v) === n);
    return hit ? player : 0;
  }
}

